(* Lesson 15 -- Sequential Function Chart (SFC): a Batch Sequencer *)

VAR
    Step        : INT;   (* current SFC step, 0..3                    *)
    Start       : BOOL;  (* N.O. start PB -> XIC (as-is)              *)
    Level_Full  : BOOL;  (* hi-level float -> XIC (as-is): TRUE=full  *)
    Temp_OK     : BOOL;  (* thermostat    -> XIC (as-is): TRUE=at temp*)
    Level_Empty : BOOL;  (* lo-level float -> XIC (as-is): TRUE=empty *)
    Fill_Valve  : BOOL;  (* output *)
    Heater      : BOOL;  (* output *)
    Drain_Valve : BOOL;  (* output *)
END_VAR

(* ----- YOUR LOGIC : write your answer between these two lines ----- *)
CASE Step OF
    0:
        Fill_Valve := FALSE; Heater := FALSE; Drain_Valve := FALSE;
        IF Start THEN Step := 1; END_IF;
    1:
        Fill_Valve := TRUE;
        IF Level_Full THEN Fill_Valve := FALSE; Step := 2; END_IF;
    2:
        Heater := TRUE;
        IF Temp_OK THEN Heater := FALSE; Step := 3; END_IF;
    3:
        Drain_Valve := TRUE;
        IF Level_Empty THEN Drain_Valve := FALSE; Step := 0; END_IF;
END_CASE;
(* ------------------------------------------------------------------ *)
